import {loadCandidateCatalog,getPresetFit} from './src/fitting/catalog.ts';
import {makeMiningRun} from './src/scenarios/fitting.ts';
import {parseExperimentJson} from './src/io/fitting-json.ts';
import {parseResultJson} from './src/io/fitting-result.ts';
import {createRun,runChunk,result} from './src/runner/run.ts';
import {FittingWorkspace} from './src/app/fitting-workspace.ts';
const old='ship-fitting-0.2.1', next='ship-fitting-0.2.2';
const created=makeMiningRun(getPresetFit('pony:2',old),loadCandidateCatalog(old),{durationSeconds:1});
if(!created.ok) throw Error(JSON.stringify(created));
const pristine=structuredClone(created.value);
const forged=structuredClone(pristine); forged.catalogVersion=forged.resolvedShip.fit.catalogVersion=next;
const removedId=forged.resolvedShip.fit.assignments['signature-2'];
delete forged.resolvedShip.fit.assignments['signature-2']; delete forged.resolvedShip.fit.instances[removedId];
const run=createRun('review-P04-extra-roster',forged); runChunk(run,20000); const measured=result(run);
const wire=JSON.stringify(measured,(_,v)=>ArrayBuffer.isView(v)?Array.from(v):v);
const workspace=new FittingWorkspace(getPresetFit('pony:1'),loadCandidateCatalog());
const before=JSON.stringify(workspace.snapshot());
const imported=workspace.importDocument(wire);
console.log(JSON.stringify({oldLegalAccepted:parseExperimentJson(JSON.stringify(pristine)).ok,forgedExperimentAccepted:parseExperimentJson(JSON.stringify(forged)).ok,forgedResultAccepted:parseResultJson(wire).ok,forgedWorkspaceResultAccepted:imported.ok,workspaceChanged:before!==JSON.stringify(workspace.snapshot()),runCompleted:measured.status,time:measured.state.timeSeconds,bufferId:removedId,bufferStateJ:measured.state.buffersJ[removedId],retainedRuntimeBuffers:Object.keys(measured.spec.resolvedShip.bufferCapacityJ),fitHasExtraInstance:Object.hasOwn(measured.spec.resolvedShip.fit.instances,removedId),rosterHasExtraInstance:measured.spec.resolvedShip.instances.some(i=>i.id===removedId)},null,2));
